assert len(REAL_CASES) == 15
for case in REAL_CASES:
    gold = case["gold"]
    variants = [{"text": case["text"], "answer": gold},
                {"text": case["text"], "answer": "999999999999999999999"},
                {"text": case["text"] + "\n#### 999999999999999999999", "answer": gold}]
    scores = runpy.run_path(str(verifier), init_globals={"SCORE_INPUT": variants})["SCORE_OUTPUT"]
    assert scores[0]["correct"], (case["id"], case["sample_index"], scores[0])
    assert scores[1]["status"] == "incorrect" and scores[1]["extracted"] == scores[0]["extracted"], case["id"]
    assert scores[2]["status"] == "ambiguous" and not scores[2]["correct"], case["id"]
    checks += 3

